function useNetworkStatus() {
  const [isOnline, setIsOnline] = reactExports.useState(() => navigator.onLine);
  const [wasOffline, setWasOffline] = reactExports.useState(false);
  const wasOfflineRef = reactExports.useRef(false);
  const handleOnline = reactExports.useCallback(() => {
    setIsOnline(true);
    if (wasOfflineRef.current) {
      setWasOffline(true);
      wasOfflineRef.current = false;
    }
  }, []);
  const handleOffline = reactExports.useCallback(() => {
    setIsOnline(false);
    setWasOffline(false);
    wasOfflineRef.current = true;
  }, []);
  reactExports.useEffect(() => {
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, [handleOnline, handleOffline]);
  reactExports.useEffect(() => {
    if (wasOffline) {
      const id2 = setTimeout(() => setWasOffline(false), 3500);
      return () => clearTimeout(id2);
    }
  }, [wasOffline]);
  return { isOnline, wasOffline };
}
